package com.fuelflex.platform.operations.entity;
import java.math.BigDecimal;import java.time.OffsetDateTime;import java.util.UUID;import com.fuelflex.platform.*;import com.fuelflex.platform.fuelmeter.entity.FuelMeter;import com.fuelflex.platform.organization.entity.Organization;import com.fuelflex.platform.product.entity.Product;import com.fuelflex.platform.station.entity.Station;import com.fuelflex.platform.tank.entity.Tank;import com.fuelflex.platform.tariffcategory.entity.TariffCategory;import com.fuelflex.platform.user.entity.User;import jakarta.persistence.*;import lombok.*;
@Entity @Table(name="internal_consumptions") @Getter @Setter @NoArgsConstructor public class InternalConsumption{
 @Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="organization_id")private Organization organization;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="station_id")private Station station;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="operational_day_id")private OperationalDay operationalDay;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="shift_assignment_id")private PumpShiftAssignment shiftAssignment;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="pump_attendant_id")private User pumpAttendant;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="fuel_meter_id")private FuelMeter fuelMeter;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="tank_id")private Tank tank;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="product_id")private Product product;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="tariff_category_id")private TariffCategory tariffCategory;@Column(nullable=false,precision=19,scale=3)private BigDecimal quantity;@Column(name="unit_price",nullable=false,precision=19,scale=3)private BigDecimal unitPrice;@Column(name="total_amount",nullable=false,precision=19,scale=3)private BigDecimal totalAmount;@Column(name="usage_beneficiary",nullable=false,length=180)private String usageBeneficiary;@Column(length=1000)private String observation;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="recorded_by")private User recordedBy;@Column(name="recorded_at",nullable=false)private OffsetDateTime recordedAt;@PrePersist void create(){if(recordedAt==null)recordedAt=OffsetDateTime.now();}}
